/* Piano Hero in Etude's design language: serif for what's being learned, Inter for the interface,
   pressable things with a 3 px bottom edge, one green main button, gold only for stars. */
html, body { margin: 0; padding: 0; background: transparent; }
[hidden] { display: none !important; }
.ph {
  --ink: var(--foreground, #ececec);
  --mut: var(--muted-foreground, #9b9b9b);
  --line: var(--border, #2d2d2d);
  --surf: color-mix(in srgb, var(--ink) 5%, transparent);
  --surf2: color-mix(in srgb, var(--ink) 10%, transparent);
  --surf3: color-mix(in srgb, var(--ink) 18%, transparent);
  --green: #3fae52; --greenInk: #2a7d39; --gold: #f2c14e; --amber: #d4952a;
  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, P052, Georgia, serif;
  --sans: var(--font-sans, Inter, -apple-system, system-ui, sans-serif);
  position: relative;
  font: 14.5px/1.5 var(--sans); color: var(--ink);
  -webkit-font-smoothing: antialiased; user-select: none; -webkit-user-select: none;
}
.ph * { box-sizing: border-box; }
html.solo body { background: #141414; min-height: 100vh; }
html.solo .ph { max-width: 1120px; margin: 0 auto; padding: 28px 28px 40px; }

.ph-eyebrow { font-size: 12px; font-weight: 700; letter-spacing: .13em; text-transform: uppercase; color: var(--mut); }
.ph-title { font: 600 32px/1.12 var(--serif); letter-spacing: -.01em; margin: 4px 0 0; }
.ph-serif { font-family: var(--serif); }
.ph-muted { color: var(--mut); }
.grow { flex: 1; }

/* buttons */
.ph-btn, .ph-pri, .ph-tile, .ph-seg, .ph-step, .ph-back, .ph-chip { all: unset; box-sizing: border-box; cursor: pointer; }
.ph-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px; white-space: nowrap;
  font-weight: 600; font-size: 14px; line-height: 1.2; padding: 8px 14px; border-radius: 12px; color: var(--ink);
  background: var(--surf); border: 1.5px solid var(--line); box-shadow: 0 3px 0 var(--line);
  transition: transform .06s, box-shadow .06s, border-color .15s;
}
.ph-btn:hover { border-color: var(--surf3); }
.ph-btn:active { transform: translateY(2px); box-shadow: 0 1px 0 var(--line); }
.ph-pri {
  display: inline-flex; align-items: center; justify-content: center; gap: 10px; white-space: nowrap;
  font-weight: 650; font-size: 15px; line-height: 1.2; padding: 10px 22px; border-radius: 12px; color: #fff;
  background: var(--green); box-shadow: 0 3px 0 var(--greenInk); transition: transform .06s, box-shadow .06s;
}
.ph-pri:active { transform: translateY(2px); box-shadow: 0 1px 0 var(--greenInk); }
.ph kbd { font: 500 11.5px var(--sans); padding: 1px 6px; border: 0; box-shadow: none; border-radius: 5px; background: var(--surf2); color: inherit; }
.ph-pri kbd { background: rgba(255, 255, 255, .22); }
.ph-btn:focus-visible, .ph-pri:focus-visible, .ph-tile:focus-visible, .ph-step:focus-visible, .ph-seg:focus-visible, .ph-chip:focus-visible { outline: 2px solid color-mix(in srgb, var(--green) 75%, transparent); outline-offset: 2px; }
.ph-icon { padding: 6px 11px; font-size: 15px; }
.ph-btn[disabled] { opacity: .35; pointer-events: none; }

/* stars */
.ph-stars { letter-spacing: 1px; font-size: 13px; color: var(--surf3); white-space: nowrap; }
.ph-stars b { color: var(--gold); font-weight: inherit; }
.ph-total { font-weight: 650; font-variant-numeric: tabular-nums; margin-right: 6px; white-space: nowrap; }
.ph-total b { color: var(--gold); font-weight: inherit; }

/* MIDI status */
.ph-midi { display: inline-flex; align-items: center; gap: 7px; color: var(--mut); font-size: 12.5px; }
.ph-midi i { width: 7px; height: 7px; border-radius: 50%; background: var(--surf3); flex: none; }
.ph-midi.ok i { background: var(--green); box-shadow: 0 0 7px var(--green); }

/* library */
.ph-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-bottom: 6px; }
.ph-head-r { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.ph-sub { margin: 0 0 22px; }
.ph-cont { display: flex; align-items: center; gap: 20px; flex-wrap: wrap; padding: 18px 20px; border-radius: 14px; background: var(--surf); border: 1.5px solid var(--line); margin-bottom: 30px; }
.ph-cont .body { flex: 1; min-width: 220px; display: flex; flex-direction: column; gap: 4px; }
.ph-cont .t { font: 600 23px/1.2 var(--serif); }
.ph-cont .m { color: var(--mut); font-size: 13.5px; }
.ph-cont .ph-meter { margin-top: 8px; max-width: 360px; }
.ph-group { margin-bottom: 28px; }
.ph-group > .ph-eyebrow { margin-bottom: 10px; }
.ph-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(206px, 1fr)); gap: 10px; }
.ph-tile {
  display: flex; flex-direction: column; gap: 4px; padding: 13px 14px 12px; border-radius: 12px; min-height: 108px;
  background: var(--surf); border: 1.5px solid var(--line); box-shadow: 0 3px 0 var(--line);
  transition: transform .06s, box-shadow .06s, border-color .15s;
}
.ph-tile:hover { border-color: var(--surf3); }
.ph-tile:active { transform: translateY(2px); box-shadow: 0 1px 0 var(--line); }
.ph-tile .t { font: 600 16.5px/1.25 var(--serif); }
.ph-tile .a { color: var(--mut); font-size: 12.5px; }
.ph-tile .row { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-top: auto; padding-top: 8px; }
.ph-lvl { display: inline-flex; align-items: center; gap: 6px; font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--mut); }
.ph-lvl span { display: inline-flex; gap: 3px; }
.ph-lvl i { width: 6px; height: 6px; border-radius: 50%; background: var(--surf3); }
.ph-lvl i.on { background: var(--mut); }
.ph-meter { height: 4px; border-radius: 2px; background: var(--surf2); overflow: hidden; }
.ph-meter i { display: block; height: 100%; background: var(--green); border-radius: 2px; }

/* game */
.ph-game { display: flex; flex-direction: column; gap: 12px; height: 640px; }
html.solo .ph-game { height: calc(100vh - 68px); min-height: 480px; }
html.in-etude .ph-game { height: max(480px, calc(var(--etude-screen-height, 700px) - 10px)); }
.ph-ghead { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; }
.ph-back { color: var(--mut); font-weight: 600; font-size: 14px; padding: 4px 2px; }
.ph-back:hover { color: var(--ink); }
.ph-gtitle { display: flex; align-items: baseline; gap: 10px; flex: 1; min-width: 0; }
.ph-gtitle .ph-serif { font-size: 23px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; flex: 0 0 auto; max-width: 60%; }
.ph-gtitle .ph-muted { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; flex: 0 1 auto; min-width: 0; }
.ph-path { display: flex; flex-direction: column; gap: 8px; }
.ph-segs { display: flex; gap: 3px; align-items: center; height: 14px; }
.ph-seg { flex: 1; height: 8px; border-radius: 4px; background: var(--surf2); transition: height .18s, background-color .3s; min-width: 3px; }
.ph-seg.s1 { background: color-mix(in srgb, var(--green) 38%, transparent); }
.ph-seg.s2 { background: color-mix(in srgb, var(--green) 66%, transparent); }
.ph-seg.s3 { background: var(--green); }
.ph-seg.lock { cursor: default; background: var(--surf); }
.ph-seg.whole { flex: 2.5; }
.ph-seg.whole.s3 { background: var(--gold); }
.ph-seg.cur { height: 14px; }
.ph-seg.live { height: 14px; background: var(--ink) !important; opacity: .8; }
.ph-vers { flex-wrap: nowrap; }
.ph-vers .ph-chip { padding: 4px 11px; font-size: 13px; }
.ph-vers .ph-stars { font-size: 11px; letter-spacing: 0; }
.ph-meter3 { display: flex; gap: 3px; }
.ph-meter3 .ph-meter { flex: 1; }
.ph-pathinfo { display: flex; align-items: center; gap: 10px; font-size: 13.5px; flex-wrap: wrap; }
.ph-pathinfo .lbl { font-weight: 600; }
.ph-steps { display: flex; gap: 8px; flex-wrap: wrap; }
.ph-step { display: inline-flex; gap: 8px; align-items: center; padding: 6px 14px; border-radius: 999px; border: 1.5px solid var(--line); color: var(--mut); font-weight: 600; font-size: 13.5px; }
.ph-step:hover { border-color: var(--surf3); }
.ph-step .n { font-variant-numeric: tabular-nums; opacity: .6; }
.ph-step .ph-stars { font-size: 12px; }
.ph-step.cur { color: var(--green); border-color: var(--green); }
.ph-stage { position: relative; flex: 1; min-height: 240px; border-radius: 14px; overflow: hidden; background: #0b0b0d; outline: none; }
.ph-stage canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; }
.ph-intro, .ph-res { position: absolute; left: 0; right: 0; top: 0; display: flex; align-items: center; justify-content: center; flex-direction: column; text-align: center; padding: 20px; gap: 8px; color: #f1f1f1; }
.ph-intro { pointer-events: none; background: rgba(11, 11, 13, .8); }
.ph-intro .ph-eyebrow, .ph-res .ph-eyebrow { color: #9a9aa0; }
.ph-h2 { font: 600 30px/1.15 var(--serif); margin: 2px 0; letter-spacing: -.01em; }
.ph-intro p, .ph-res p { margin: 0; color: #b4b4ba; max-width: 460px; }
.ph-intro .how { font-size: 13px; color: #8d8d93; margin-top: 6px; }
.ph-intro kbd, .ph-res kbd { background: rgba(255, 255, 255, .12); }
.ph-res { bottom: 0; background: rgba(9, 9, 11, .8); gap: 10px; }
.ph-res .row { display: flex; gap: 10px; flex-wrap: wrap; justify-content: center; margin-top: 8px; }
.ph-res .ph-btn { --ink: #ececec; --line: #3a3a40; --surf: rgba(255, 255, 255, .06); --surf3: #55555c; }
.ph-big { font-size: 46px; line-height: 1; letter-spacing: 8px; color: #343439; margin-right: -8px; }
.ph-big span { display: inline-block; }
.ph-big .on { color: var(--gold); }
.ph-big .new { animation: ph-pop .6s cubic-bezier(.3, .7, .2, 1) both; }
@keyframes ph-pop { 0% { transform: scale(.2) rotate(-30deg); opacity: 0; } 60% { transform: scale(1.25) rotate(6deg); opacity: 1; } 100% { transform: none; } }
.ph-strip { display: flex; flex-wrap: wrap; gap: 4px; justify-content: center; max-width: 520px; margin-top: 2px; }
.ph-strip i { width: 9px; height: 9px; border-radius: 50%; background: var(--green); }
.ph-strip i.r { background: var(--amber); }
.ph-strip i.x { background: #4a4a50; }
.ph-unlock { display: inline-block; font-weight: 650; font-size: 13.5px; padding: 5px 13px; border-radius: 999px; background: rgba(63, 174, 82, .16); color: #7ccf8a; }
.ph-toast { position: absolute; top: 14px; left: 50%; transform: translate(-50%, -6px); padding: 6px 14px; border-radius: 999px; background: rgba(22, 22, 26, .94); color: #eee; font-weight: 600; font-size: 13.5px; opacity: 0; transition: opacity .25s, transform .25s; pointer-events: none; white-space: nowrap; }
.ph-toast.show { opacity: 1; transform: translate(-50%, 0); }
.ph-bar { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.ph-bar .ph-muted { font-size: 13px; font-variant-numeric: tabular-nums; }

/* sound gate: MIDI notes don't count as the click a browser needs before it plays sound */
.ph-gate { all: unset; box-sizing: border-box; cursor: pointer; position: absolute; inset: 0; z-index: 9; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; background: rgba(9, 9, 11, .82); color: #f1f1f1; border-radius: 14px; text-align: center; }
.ph-gate b { font: 600 26px/1.2 var(--serif); }
.ph-gate span { color: #a9a9ae; font-size: 14px; }
.ph-credit { font-size: 11.5px !important; opacity: .75; }

/* settings */
.ph-pop { position: absolute; top: 56px; right: 0; z-index: 5; width: min(340px, 100%); padding: 18px; border-radius: 14px; background: var(--card, #1b1b1b); border: 1.5px solid var(--line); box-shadow: 0 12px 40px rgba(0, 0, 0, .45); display: flex; flex-direction: column; gap: 14px; }
html.solo .ph-pop { right: 28px; top: 84px; }
.ph-pop .ph-eyebrow { margin-bottom: 6px; }
.ph-chips { display: flex; gap: 6px; flex-wrap: wrap; }
.ph-chip { font-size: 13.5px; font-weight: 600; border: 1.5px solid var(--line); border-radius: 999px; padding: 5px 12px; color: var(--mut); }
.ph-chip:hover { border-color: var(--surf3); }
.ph-chip.on { color: var(--green); border-color: var(--green); }
.ph-pop p { margin: 0; color: var(--mut); font-size: 13px; }

/* the summary Etude shows after ✓ Terminar */
.ph-sum { display: flex; flex-direction: column; gap: 16px; }
.ph-sum .big { display: flex; gap: 32px; flex-wrap: wrap; }
.ph-sum .v { font: 600 30px/1.1 var(--serif); font-variant-numeric: tabular-nums; }
.ph-sum .rows { display: flex; flex-direction: column; gap: 6px; }
.ph-sum .r { display: flex; gap: 14px; align-items: baseline; color: var(--mut); font-variant-numeric: tabular-nums; }
.ph-sum .r .t { color: var(--ink); font-weight: 500; min-width: 16em; }

@media (max-width: 560px) {
  html.in-etude .ph { padding: 8px 10px 0; }
  html.in-etude .ph-game { height: max(480px, calc(var(--etude-screen-height, 700px) - 18px)); }
  html.solo .ph { padding: 18px 14px 28px; }
  .ph-title { font-size: 26px; }
  .ph-grid { grid-template-columns: 1fr 1fr; }
  .ph-tile { min-height: 96px; padding: 11px 12px; }
  .ph-tile .t { font-size: 15px; }
  .ph-gtitle .ph-serif { font-size: 19px; }
  .ph-gtitle .ph-muted { display: none; }
  .ph-ghead { row-gap: 8px; }
  .ph-vers { order: 3; flex-basis: 100%; }
  .ph-ghead .ph-midi { display: none; }
  .ph-h2 { font-size: 24px; }
  .ph-steps { gap: 6px; flex-wrap: nowrap; }
  .ph-step { padding: 5px 10px; font-size: 13px; gap: 6px; }
  .ph-step .n { display: none; }
  .ph-pop { top: 64px; }
  .ph-big { font-size: 38px; }
}
@media (prefers-reduced-motion: reduce) { .ph * { transition: none !important; animation: none !important; } }

