// A Piano Hero session: each finished run is { s: song, p: part (0 whole song, -1 hard bit), k: step 1..3, a: %, st: stars earned }.
const log = (Array.isArray(answer?.log) ? answer.log : []).slice(0, 120)
  .filter((e) => e && typeof e.s === "string")
  .map((e) => ({ s: e.s.slice(0, 80), p: Number.isInteger(e.p) ? e.p : 0, k: Math.max(1, Math.min(3, Math.round(Number(e.k) || 1))),
                 a: Math.max(0, Math.min(100, Math.round(Number(e.a) || 0))), st: Math.max(0, Math.min(3, Math.round(Number(e.st) || 0))) }));
const seconds = Math.round(Math.min(36000000, Math.max(0, Number(answer?.ms) || 0)) / 1000);
if (!log.length) return { score: 0, feedback: "Nenhuma parte terminada.", details: { acc: null, plays: 0, stars: 0, seconds, log: [] } };
const acc = Math.round(log.reduce((s, e) => s + e.a, 0) / log.length);
const stars = log.reduce((s, e) => s + e.st, 0);
return { score: acc / 100, details: { acc, plays: log.length, stars, seconds, log } };
